import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>
#include <limits>

template <typename scalar_t>
__global__ void max_reduce_kernel(
    const scalar_t* __restrict__ x,
    scalar_t* __restrict__ out,
    int64_t d0,
    int64_t d1,
    int64_t d2,
    int64_t reduce_dim) {
    extern __shared__ unsigned char smem_raw[];
    scalar_t* smem = reinterpret_cast<scalar_t*>(smem_raw);
    const int tid = threadIdx.x;
    // For reductions over dimensions 0 and 1, map neighboring threads
    // to neighboring output columns so global loads are coalesced.
    if (reduce_dim != 2) {
        const int64_t out_idx =
            static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
        const int64_t out_numel =
            (reduce_dim == 0) ? d1 * d2 : d0 * d2;
        if (out_idx >= out_numel) {
            return;
        }
        int64_t reduce_size;
        int64_t base;
        int64_t stride;
        if (reduce_dim == 0) {
            const int64_t i = out_idx / d2;
            const int64_t j = out_idx % d2;
            reduce_size = d0;
            base = i * d2 + j;
            stride = d1 * d2;
        } else {
            const int64_t b = out_idx / d2;
            const int64_t j = out_idx % d2;
            reduce_size = d1;
            base = b * d1 * d2 + j;
            stride = d2;
        }
        scalar_t best = static_cast<scalar_t>(-INFINITY);
        for (int64_t k = 0; k < reduce_size; ++k) {
            const scalar_t v = x[base + k * stride];
            if (v != v || best != best) {
                best = v;
            } else if (v > best) {
                best = v;
            }
        }
        out[out_idx] = best;
        return;
    }
    const int64_t out_idx = static_cast<int64_t>(blockIdx.x);
    const int64_t reduce_size = d2;
    const int64_t b = out_idx / d1;
    const int64_t i = out_idx % d1;
    const int64_t base = b * d1 * d2 + i * d2;
    const int64_t stride = 1;
    scalar_t best = static_cast<scalar_t>(-INFINITY);
    for (int64_t k = tid; k < reduce_size; k += blockDim.x) {
        const scalar_t v = x[base + k * stride];
        if (v != v || best != best) {
            best = v;
        } else if (v > best) {
            best = v;
        }
    }
    smem[tid] = best;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            const scalar_t a = smem[tid];
            const scalar_t bval = smem[tid + s];
            if (a != a || bval != bval) {
                smem[tid] = (a != a) ? a : bval;
            } else if (bval > a) {
                smem[tid] = bval;
            }
        }
        __syncthreads();
    }
    if (tid == 0) {
        out[out_idx] = smem[0];
    }
}

at::Tensor max_reduce_cuda(const at::Tensor& input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 3, "input must be a 3D tensor");
    TORCH_CHECK(
        input.scalar_type() == at::kFloat ||
        input.scalar_type() == at::kDouble ||
        input.scalar_type() == at::kHalf,
        "only float16, float32, and float64 are supported");

    auto x = input.contiguous();

    if (dim < 0) {
        dim += 3;
    }
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be in [-3, 2]");

    const int64_t d0 = x.size(0);
    const int64_t d1 = x.size(1);
    const int64_t d2 = x.size(2);

    std::vector<int64_t> out_sizes;
    if (dim == 0) {
        out_sizes = {d1, d2};
    } else if (dim == 1) {
        out_sizes = {d0, d2};
    } else {
        out_sizes = {d0, d1};
    }

    auto out = at::empty(out_sizes, x.options());
    const int64_t out_numel = out.numel();

    constexpr int threads = 256;
    const dim3 blocks(
        static_cast<unsigned int>(dim == 2 ? out_numel : (out_numel + threads - 1) / threads));
    const size_t shared_bytes = (dim == 2) ? threads * x.element_size() : 0;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x.scalar_type(),
        "max_reduce_cuda",
        [&] {
            max_reduce_kernel<scalar_t><<<blocks, threads, shared_bytes, stream>>>(
                x.data_ptr<scalar_t>(),
                out.data_ptr<scalar_t>(),
                d0,
                d1,
                d2,
                dim);
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""


_ext = load_inline(
    name="max_reduce_cuda_extension",
    cpp_sources="#include <torch/extension.h>\n\nat::Tensor max_reduce_cuda(const at::Tensor& input, int64_t dim);\n",
    cuda_sources=_cuda_src,
    functions=["max_reduce_cuda"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.max_reduce_cuda(x, self.dim)

